export function blueNoiseRanks() {
  const bytes = atob(encoded), ranks = new Uint16Array(bytes.length / 2);
  for (let i = 0; i < ranks.length; i++)
    ranks[i] = bytes.charCodeAt(i * 2) | (bytes.charCodeAt(i * 2 + 1) << 8);
  return ranks;
}
